"""Draft generator for the step 2d field tables (Codex X-156 C173: READ-ONLY drafting, WP13 manifest as the source). Reads only
Codex/WP13_BOSS01_NATIVE_FIELDS.csv and writes D2D_FIELD_TABLES_DRAFT.md next to this file. No product code, no ImportText adapter, no hydration.
The classification column is a PROPOSAL by name/type rules (printed in the document) and every row that the rules cannot place is marked REVIEW; it is not a decision."""
import collections
import csv
import os
import re

HERE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.join(HERE, "..", "..", "Codex", "WP13_BOSS01_NATIVE_FIELDS.csv")
OUT = os.path.join(HERE, "D2D_FIELD_TABLES_DRAFT.md")

# Component order of the live attachment (RPGPlayerMovesSubsystem.cpp Attach, boss branch) = the order the adapters must keep.
ORDER = ["BossStagger", "BossPhases", "BossEncounter", "BossDormantWake", "BossPosture", "BossDeath", "BossLook", "BossBleed", "AttackTracker",
         "BossCloseClipSwap", "BossShockwave", "BossLowSweep", "BossHealPunish", "BossHud", "PlayerMovesSubsystem"]
SHARED = {"BossRules", "BossMath", "BossClips", "BossDamage", "BossInterrupt", "BossJavelin", "BossRemains", "TelegraphRules", "BossDormantWakeRules", "BossCloseClipSwapRules"}

RUNTIME = re.compile(r"^(Loaded\w*|\w*Component|\w*Components|Widget|Plate|TrailBar|HealthBar|PostureBar|\w*TextBlock|NameText|SubtitleText|Encounter|Phases|Posture|Stagger|HiddenPackWeapons|Materials|OnVictory)$")
ABI = re.compile(r"(ClassName|MontagesName|AbilityPrefix|AbilityTag|Socket|MoveId|MontageName|FallbackMontageName)$")
POLICY = re.compile(r"^(bEnabled|bTest\w*|bGuard\w*|bUse\w*|bPin\w*|bLock\w*|bHide\w*|bRespond\w*|bCancel\w*|bCritical\w*|bHold\w*|bPause\w*|bFireball\w*|bResetOn\w*|bVeto\w*|bAuthored\w*|bBranch\w*|DeathMode)$")
TEXT = re.compile(r"(Text|Name|Subtitle)$")


def classify(row):
    field, kind = row["FieldOrRole"], row["ValueKind"]
    if RUNTIME.match(field):
        return "runtime state / cache (never in a definition)"
    if kind == "ASSET_REFERENCE_DEFAULT" or row["Class"] == "NEEDS_EDITOR":
        return "content: asset reference (editor evidence: skeleton, length, ancestry)"
    if row["ValueExpression"].startswith("NSLOCTEXT"):
        return "content: presentation text (localizable)"
    if ABI.search(field):
        return "pack ABI string (invariant of the reference pack; content only if a boss differs)"
    if POLICY.match(field):
        return "policy / test flag (decide per field: Encounter policy vs test-only)"
    if re.search(r"(Seconds|Time|Cooldown|Speed|Rate|Range|Radius|Damage|Scale|Fraction|Threshold|Multiplier|Degrees|Height|Gap|Clearance|Reach|Thickness|Count|Max|Min|Increase|Restarts|Delay)", field):
        return "content: tuning number (units in the name)"
    return "REVIEW (rules cannot place it)"


def component(path):
    name = os.path.basename(path)
    base = name.rsplit(".", 1)[0]
    return base[3:] if base.startswith("RPG") else base


rows = list(csv.DictReader(open(SRC, encoding="utf-8")))
by = collections.defaultdict(list)
for r in rows:
    by[component(r["Source"])].append(r)

out = []
out.append("# Step 2d field tables: DRAFT (Claude, read-only, 2026-10-26)\n")
out.append("Authority: `CODEX_LEAD_DECISIONS_C170_C173.md` (C173: read-only drafting from the WP13 manifest; no product adapter, no mechanical ImportText, no hydration). Source: `Codex/WP13_BOSS01_NATIVE_FIELDS.csv` (%d native rows; sha256 of the CSV is the manifest's). Generated by `gen_field_tables.py` in this folder; NOT BUILT, NOT RUN against the game. The classification is a PROPOSAL by the name/type rules at the end of this file; every `REVIEW` row is an open decision, and every asset row still needs editor evidence.\n" % len(rows))
out.append("## How each row is used by 2d\n")
out.append("- **Apply timing**: content and policy fields are applied by a typed `ConfigureBeforeRegistration` adapter BEFORE `RegisterComponent` (the components read their fields in the constructor and `BeginPlay`; Boss01 values must be in place at registration). Runtime state/caches are never in a definition and are not applied.\n- **Parity assertion (generic, per property)**: an automation test constructs the component with `NewObject`, reads each reflected property by name and compares it with the adapter value produced from the Boss01 definition built from the SAME compiled defaults; plus the per-component driver listed in `Codex/PROMOTION_STEP2.md` run before and after. A property whose default is `(uninitialized here)` needs the constructor/serialized override read first (column `Default`).\n- **Order**: adapters keep the live registration order (the tables below are in that order): Stagger, Phases, Encounter, DormantWake, Posture, Death(OwnClip), Look, Bleed, AttackTracker, CloseClipSwap, Shockwave, LowSweep, HealPunish, Hud (DamageResolver/TraceGuard/TraceAudit/CombatDebug/Legend carry no Boss01 content fields in the manifest and are invariants of the compatibility path).\n")

summary = []
sections = []
for comp in ORDER:
    rs = by.get(comp, [])
    props = [r for r in rs if r["ValueKind"] in ("CXX_PROPERTY_DEFAULT", "ASSET_REFERENCE_DEFAULT") and r["Source"].endswith(".h")]
    others = [r for r in rs if r not in props]
    cls = collections.Counter(classify(r) for r in props)
    roles = collections.Counter(r["FieldOrRole"] if r["FieldOrRole"].isupper() else "FIELD" for r in others)
    summary.append((comp, len(props), cls, roles))
    sec = ["\n## %s\n" % comp,
           "Source files: %s. Declared properties: %d. Other manifest rows (code literals, state seeds, diagnostics, asset bindings in `.cpp`): %d (%s).\n" % (
               ", ".join(sorted({os.path.basename(r["Source"]) for r in rs})), len(props), len(others), ", ".join("%s %d" % kv for kv in roles.most_common(6))),
           "| Line | Property | Default (source) | Proposed D02 field | Class | Proposal |", "|---|---|---|---|---|---|"]
    for r in sorted(props, key=lambda x: int(x["Line"])):
        default = r["ValueExpression"].replace("|", "/").replace("\n", " ")[:70]
        sec.append("| %s:%s | `%s` | `%s` | %s | %s | %s |" % (os.path.basename(r["Source"]), r["Line"], r["FieldOrRole"], default, r["DefinitionField"][:60].replace("|", "/"), r["Class"], classify(r)))
    sections.append("\n".join(sec))

out.append("## Summary by component (proposal counts)\n")
out.append("| Component | Declared properties | Proposal counts |\n|---|---|---|")
for comp, n, cls, roles in summary:
    out.append("| %s | %d | %s |" % (comp, n, "; ".join("%s: %d" % (k.split(" (")[0], v) for k, v in cls.most_common())))
shared_rows = sum(len(by.get(s, [])) for s in SHARED)
out.append("\nShared helper files (%s) carry %d manifest rows (rule constants and tables: invariants unless a decision says otherwise; no per-boss content proposed here).\n" % (", ".join(sorted(SHARED)), shared_rows))
out.append("\n".join(sections))
out.append("\n## Rules used for the proposal column\n")
out.append("1. Names matching `Loaded*`, `*Component(s)`, widget pointers, `Encounter/Phases/Posture/Stagger` back-pointers, `Materials`, `HiddenPackWeapons`, `OnVictory` = runtime state or cache.\n2. `ASSET_REFERENCE_DEFAULT` rows and every `NEEDS_EDITOR` row = asset reference content; the effective value needs the editor readback (skeleton, length, class ancestry), export text is not a live value.\n3. `NSLOCTEXT(...)` defaults = presentation text.\n4. Names ending `ClassName`, `MontagesName`, `AbilityPrefix`, `AbilityTag`, `Socket`, `MoveId`, `MontageName` = pack ABI strings (invariant of the reference pack).\n5. `bEnabled`, `bTest*`, `bGuard*`, `bUse*`, `bPin*`, `bLock*`, `bHide*`, `bRespond*`, `bCancel*`, `bCritical*`, `bHold*`, `bPause*`, `bFireball*`, `bResetOn*`, `bVeto*`, `bAuthored*`, `bBranch*`, `DeathMode` = policy or test flag: each needs a decision (Encounter policy vs test-only vs invariant).\n6. Names containing time, speed, range, radius, damage, scale, fraction, threshold, multiplier, degrees, height, gap, clearance, reach, thickness, count, max/min = tuning number.\n7. Anything else = `REVIEW`.\n\nNot covered here (still OPEN, by design): the `.cpp` literal rows (move timing tuples, state seeds, diagnostics) that the manifest marks `NEEDS_SEAM`; they need the seam decision per row (content vs invariant) before any table row can be written for them. `AttackTracker.cpp` lines 33 to 63 (A2 commit 1.68, active 1.93..2.11, recovery 3.14; the four exact `AddClose` tuples) are code-observer compatibility timings, not to be overwritten from the sidecar.\n")
open(OUT, "w", encoding="utf-8").write("\n".join(out))
print("wrote", OUT, sum(n for _, n, _, _ in summary), "declared properties in", len(ORDER), "components")
